dashboard.definition:
{
	"title": "Statewide Exercise - Modern Dashboard Studio",
	"description": "Modern Dashboard Studio JSON conversion of statewide_exercise_v1.xml with tabbed layout, refreshed searches, token filters, drilldown detail panels, and enterprise network monitoring visuals.",
	"inputs": {
		"input_client_type": {
			"options": {
				"defaultValue": "*",
				"items": [
					{
						"label": "All clients",
						"value": "*"
					},
					{
						"label": "Wireless",
						"value": "Wireless"
					},
					{
						"label": "Wired",
						"value": "Wired"
					}
				],
				"token": "client_type_tok"
			},
			"title": "Client Type",
			"type": "input.dropdown"
		},
		"input_close_issue": {
			"containerOptions": {
				"visibility": {
					"showConditions": [
						"condition_issue_selected"
					]
				}
			},
			"eventHandlers": [
				{
					"options": {
						"tokens": [
							{
								"token": "selected_issue",
								"value": ""
							},
							{
								"token": "selected_issue_priority",
								"value": ""
							}
						]
					},
					"type": "drilldown.setToken"
				}
			],
			"options": {
				"label": "Close Details"
			},
			"title": "",
			"type": "input.button"
		},
		"input_refresh_rate": {
			"options": {
				"defaultValue": "60s",
				"items": [
					{
						"label": "60 seconds",
						"value": "60s"
					},
					{
						"label": "5 minutes",
						"value": "300s"
					},
					{
						"label": "15 minutes",
						"value": "900s"
					}
				],
				"token": "refresh_tok"
			},
			"title": "Refresh",
			"type": "input.dropdown"
		},
		"input_site_filter": {
			"options": {
				"defaultValue": "*",
				"token": "site_tok"
			},
			"title": "Site Filter",
			"type": "input.text"
		},
		"input_time_range": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "time_tok"
			},
			"title": "Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"earliest": "$time_tok.earliest$",
						"latest": "$time_tok.latest$"
					}
				}
			},
			"ds.spl2": {
				"options": {
					"queryParameters": {
						"earliest": "$time_tok.earliest$",
						"latest": "$time_tok.latest$"
					}
				}
			},
			"global": {
				"options": {
					"refresh": "$refresh_tok$",
					"refreshType": "delay"
				}
			}
		},
		"tokens": {
			"default": {
				"client_type_tok": {
					"value": "*"
				},
				"refresh_tok": {
					"value": "60s"
				},
				"selected_client": {
					"value": ""
				},
				"selected_issue": {
					"value": ""
				},
				"selected_issue_priority": {
					"value": ""
				},
				"site_tok": {
					"value": "*"
				}
			}
		},
		"visualizations": {
			"global": {
				"showLastUpdated": true,
				"showProgressBar": true
			}
		}
	},
	"visualizations": {
		"viz_about_content": {
			"options": {
				"backgroundColor": "#131a23",
				"fontColor": "#ecf0f5",
				"markdown": "### Purpose\n\nThis Dashboard Studio definition modernizes `statewide_exercise_v1.xml` into a four-tab operational view for statewide network activation exercises.\n\n### Preserved searches\n\nAll SPL data sources embedded in the existing `statewide_exercise_v1.xml` CDATA definition are copied into this JSON. New `ds_mod_*` searches add tokenized filters, reusable base searches, 60-second refresh behavior, issue drilldowns, and the executive health distribution panels.\n\n### Data sources\n\n- `cisco:dnac:clienthealth`: wired and wireless health KPIs, client counts, 24-hour and 7-day trends.\n- `cisco:dnac:client`: SSID, OS, site, traffic, onboarding, and per-client detail tables.\n- `cisco:dnac:devicehealth`: device type KPIs, health distribution, inventory, and total fleet summary.\n- `cisco:dnac:issue`: active issue summaries and row-click detail panels.\n\n### Interaction model\n\n- Global time range controls dashboard searches through `$time_tok$`.\n- Refresh rate defaults to 60 seconds through `$refresh_tok$`.\n- Client Type and Site Filter tokens narrow client distribution/detail searches.\n- Selecting an issue row sets `$selected_issue$` and opens the Issue Detail panel. Use Close Details to clear the token.\n\n### Health color policy\n\n- `>=95%`: green `#4cbf7f`.\n- `80-95%`: yellow `#f0c243`.\n- `<80%`: red `#fa5762`.\n\n### Studio schema notes\n\nDashboard Studio source JSON uses `splunk.*` visualization type IDs. The old `viz.*` syntax is legacy and is migrated by Splunk when opened in current Studio. JSON does not support comments, so implementation notes are encoded here and in visualization descriptions to keep this definition importable."
			},
			"showLastUpdated": false,
			"showProgressBar": false,
			"title": "Metric Reference",
			"type": "splunk.markdown"
		},
		"viz_client_activity_onboarding": {
			"dataSources": {
				"primary": "ds_mod_client_activity_7d"
			},
			"description": "Daily active clients with average onboarding duration as an overlay.",
			"options": {
				"backgroundColor": "#131a23",
				"dataValuesDisplay": "all",
				"legendDisplay": "right",
				"overlayFields": [
					"Avg Onboarding (ms)"
				],
				"seriesColorsByField": {
					"Active Clients": "#9b5ff5",
					"Avg Onboarding (ms)": "#049fd9"
				},
				"showOverlayY2Axis": true,
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleText": "Active Clients",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#649ef5",
					"#4cbf7f",
					"#f0c243",
					"#fa5762",
					"#9ca6ff",
					"#9b5ff5",
					"#049fd9",
					"#00bceb",
					"#f7782f"
				]
			},
			"title": "Client Activity and Onboarding",
			"type": "splunk.bar"
		},
		"viz_client_details": {
			"context": {
				"healthColorRange": [
					{
						"to": 80,
						"value": "#fa5762"
					},
					{
						"from": 80,
						"to": 95,
						"value": "#f0c243"
					},
					{
						"from": 95,
						"value": "#4cbf7f"
					}
				]
			},
			"dataSources": {
				"primary": "ds_mod_client_details"
			},
			"description": "Top connected clients by traffic. Select a row to inspect client detail.",
			"eventHandlers": [
				{
					"options": {
						"tokens": [
							{
								"key": "row.Client.value",
								"token": "selected_client"
							}
						]
					},
					"type": "drilldown.setToken"
				}
			],
			"options": {
				"backgroundColor": "#131a23",
				"columnFormat": {
					"Health %": {
						"rowColors": "> table | seriesByName(\"Health %\") | rangeValue(healthColorRange)"
					},
					"Traffic (GB)": {
						"textOverflow": "break-word"
					}
				},
				"count": 20,
				"drilldown": "row",
				"fontSize": "small",
				"showInternalFields": false,
				"tableFormat": {
					"headerBackgroundColor": "#1c2738",
					"headerColor": "#ecf0f5"
				}
			},
			"title": "Wireless Client Details",
			"type": "splunk.table"
		},
		"viz_client_distribution": {
			"context": {
				"healthColorRange": [
					{
						"to": 80,
						"value": "#fa5762"
					},
					{
						"from": 80,
						"to": 95,
						"value": "#f0c243"
					},
					{
						"from": 95,
						"value": "#4cbf7f"
					}
				]
			},
			"dataSources": {
				"primary": "ds_mod_client_distribution_score"
			},
			"description": "Percentage of clients reporting GOOD health.",
			"options": {
				"backgroundColor": "#131a23",
				"majorColor": "> primary | seriesByName('healthy_pct') | lastPoint() | rangeValue(healthColorRange)",
				"majorValue": "> primary | seriesByName('healthy_pct') | lastPoint()",
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"unit": "%"
			},
			"title": "Client Distribution",
			"type": "splunk.singlevalueradial"
		},
		"viz_client_health_over_time": {
			"dataSources": {
				"primary": "ds_cs_count_over_time"
			},
			"description": "Stacked client health distribution across wired and wireless clients.",
			"options": {
				"backgroundColor": "#131a23",
				"nullValueDisplay": "connect",
				"seriesColorsByField": {
					"Fair Count": "#f0c243",
					"Good Count": "#4cbf7f",
					"Idle Count": "#a6adb6",
					"Poor Count": "#fa5762"
				},
				"showYMajorGridLines": true,
				"splitByLayout": "trellis",
				"stackMode": "stacked",
				"trellisColumns": 2,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleText": "Clients",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#649ef5",
					"#4cbf7f",
					"#f0c243",
					"#fa5762",
					"#9ca6ff",
					"#9b5ff5",
					"#049fd9",
					"#00bceb",
					"#f7782f"
				],
				"lineWidth": 2,
				"markerDisplay": "outlined"
			},
			"title": "Client Health Over Time",
			"type": "splunk.area"
		},
		"viz_client_health_score": {
			"context": {
				"healthColorRange": [
					{
						"to": 80,
						"value": "#fa5762"
					},
					{
						"from": 80,
						"to": 95,
						"value": "#f0c243"
					},
					{
						"from": 95,
						"value": "#4cbf7f"
					}
				]
			},
			"dataSources": {
				"primary": "ds_kpi_cs_health"
			},
			"description": "Average client health score across wired and wireless clients.",
			"options": {
				"backgroundColor": "#131a23",
				"majorColor": "> majorValue | rangeValue(healthColorRange)",
				"majorFontSize": 38,
				"majorValue": "> primary | seriesByName('Client Health Score') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true,
				"showSparklineAreaGraph": true,
				"showSparklineTooltip": true,
				"showTrendIndicator": true,
				"sparklineAreaColor": "> majorValue | rangeValue(healthColorRange)",
				"sparklineDisplay": "below",
				"sparklineNullValueDisplay": "connect",
				"sparklineStrokeColor": "> majorValue | rangeValue(healthColorRange)",
				"trendDisplay": "percent",
				"unit": "%"
			},
			"title": "Active Client Score",
			"type": "splunk.singlevalue"
		},
		"viz_client_location_distribution": {
			"dataSources": {
				"primary": "ds_mod_client_location_dist"
			},
			"description": "Top sites by connected client count.",
			"options": {
				"backgroundColor": "#131a23",
				"dataValuesDisplay": "all",
				"legendDisplay": "off",
				"orientation": "horizontal",
				"seriesColors": [
					"#649ef5"
				],
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"title": "Client Distribution by Location",
			"type": "splunk.bar"
		},
		"viz_client_os_distribution": {
			"dataSources": {
				"primary": "ds_mod_client_os_dist"
			},
			"description": "Operating system breakdown for filtered clients.",
			"options": {
				"backgroundColor": "#131a23",
				"dataValuesDisplay": "all",
				"legendDisplay": "off",
				"orientation": "horizontal",
				"seriesColors": [
					"#a6adb6"
				],
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			},
			"title": "Client Distribution by OS",
			"type": "splunk.bar"
		},
		"viz_client_total": {
			"dataSources": {
				"primary": "ds_kpi_cs_total"
			},
			"description": "Total unique connected clients in the selected time range.",
			"options": {
				"backgroundColor": "#131a23",
				"majorColor": "#ecf0f5",
				"majorFontSize": 38,
				"majorValue": "> primary | seriesByName('Total Connected Clients') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true,
				"showSparklineAreaGraph": true,
				"showSparklineTooltip": true,
				"showTrendIndicator": true,
				"sparklineAreaColor": "rgba(100,158,245,0.18)",
				"sparklineDisplay": "below",
				"sparklineNullValueDisplay": "connect",
				"sparklineStrokeColor": "#649ef5",
				"trendDisplay": "percent"
			},
			"title": "Total Active Clients",
			"type": "splunk.singlevalue"
		},
		"viz_ex_ap_health": {
			"context": {
				"healthColorRange": [
					{
						"to": 80,
						"value": "#fa5762"
					},
					{
						"from": 80,
						"to": 95,
						"value": "#f0c243"
					},
					{
						"from": 95,
						"value": "#4cbf7f"
					}
				]
			},
			"dataSources": {
				"primary": "ds_mod_device_health_ap"
			},
			"description": "Reachable and managed access points as a percentage of total AP inventory.",
			"options": {
				"backgroundColor": "#131a23",
				"gaugeColor": "> primary | seriesByName('health_pct') | lastPoint() | rangeValue(healthColorRange)",
				"labelDisplay": "percentage",
				"orientation": "horizontal",
				"value": "> primary | seriesByName('health_pct') | lastPoint()",
				"valueDisplay": "percentage"
			},
			"title": "Access Points",
			"type": "splunk.fillergauge"
		},
		"viz_ex_device_health_distribution": {
			"dataSources": {
				"primary": "ds_mod_device_health_distribution"
			},
			"description": "Fleet-wide healthy, fair, and poor device distribution.",
			"options": {
				"backgroundColor": "#131a23",
				"dataValuesDisplay": "all",
				"legendDisplay": "bottom",
				"orientation": "horizontal",
				"seriesColorsByField": {
					"Fair": "#f0c243",
					"Healthy": "#4cbf7f",
					"Poor": "#fa5762"
				},
				"showYMajorGridLines": true,
				"stackMode": "stacked",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#649ef5",
					"#4cbf7f",
					"#f0c243",
					"#fa5762",
					"#9ca6ff",
					"#9b5ff5",
					"#049fd9",
					"#00bceb",
					"#f7782f"
				]
			},
			"title": "Device Health Distribution",
			"type": "splunk.bar"
		},
		"viz_ex_device_inventory": {
			"dataSources": {
				"primary": "ds_mod_device_inventory_bar"
			},
			"description": "Reachable versus attention-needed devices by network role.",
			"options": {
				"backgroundColor": "#131a23",
				"dataValuesDisplay": "all",
				"legendDisplay": "bottom",
				"orientation": "horizontal",
				"seriesColorsByField": {
					"Healthy": "#4cbf7f",
					"NeedsAttention": "#fa5762"
				},
				"showYMajorGridLines": true,
				"stackMode": "stacked",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#649ef5",
					"#4cbf7f",
					"#f0c243",
					"#fa5762",
					"#9ca6ff",
					"#9b5ff5",
					"#049fd9",
					"#00bceb",
					"#f7782f"
				]
			},
			"title": "Device Inventory",
			"type": "splunk.bar"
		},
		"viz_ex_device_total_radial": {
			"context": {
				"healthColorRange": [
					{
						"to": 80,
						"value": "#fa5762"
					},
					{
						"from": 80,
						"to": 95,
						"value": "#f0c243"
					},
					{
						"from": 95,
						"value": "#4cbf7f"
					}
				]
			},
			"dataSources": {
				"primary": "ds_mod_device_summary_total"
			},
			"description": "Total discovered network devices, with radial color based on overall device health.",
			"options": {
				"backgroundColor": "#131a23",
				"majorColor": "> primary | seriesByName('health_pct') | lastPoint() | rangeValue(healthColorRange)",
				"majorValue": "> primary | seriesByName('total') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off"
			},
			"title": "Device Summary - Total",
			"type": "splunk.singlevalueradial"
		},
		"viz_ex_firewall_health": {
			"context": {
				"healthColorRange": [
					{
						"to": 80,
						"value": "#fa5762"
					},
					{
						"from": 80,
						"to": 95,
						"value": "#f0c243"
					},
					{
						"from": 95,
						"value": "#4cbf7f"
					}
				]
			},
			"dataSources": {
				"primary": "ds_mod_device_health_firewalls"
			},
			"description": "Reachable and managed firewalls as a percentage of total firewall inventory.",
			"options": {
				"backgroundColor": "#131a23",
				"gaugeColor": "> primary | seriesByName('health_pct') | lastPoint() | rangeValue(healthColorRange)",
				"labelDisplay": "percentage",
				"orientation": "horizontal",
				"value": "> primary | seriesByName('health_pct') | lastPoint()",
				"valueDisplay": "percentage"
			},
			"title": "Firewalls",
			"type": "splunk.fillergauge"
		},
		"viz_ex_issue_detail_modal": {
			"containerOptions": {
				"visibility": {
					"showConditions": [
						"condition_issue_selected"
					]
				}
			},
			"dataSources": {
				"primary": "ds_mod_selected_issue_detail"
			},
			"description": "Row-click detail view for the selected active issue.",
			"options": {
				"backgroundColor": "#131a23",
				"count": 10,
				"drilldown": "none",
				"fontSize": "small",
				"showInternalFields": false,
				"tableFormat": {
					"headerBackgroundColor": "#1c2738",
					"headerColor": "#ecf0f5"
				}
			},
			"title": "Issue Detail",
			"type": "splunk.table"
		},
		"viz_ex_issues_table": {
			"containerOptions": {
				"visibility": {
					"hideConditions": [
						"condition_issue_selected"
					]
				}
			},
			"context": {
				"severityColors": [
					{
						"match": "Critical",
						"value": "rgba(220,38,38,0.22)"
					},
					{
						"match": "Warning",
						"value": "rgba(234,179,8,0.22)"
					},
					{
						"match": "Notice",
						"value": "rgba(37,99,235,0.12)"
					},
					{
						"match": "Info",
						"value": "rgba(22,163,74,0.12)"
					}
				]
			},
			"dataSources": {
				"primary": "ds_mod_exec_issues_table"
			},
			"description": "Critical and warning alerts requiring attention. Select a row to open details.",
			"eventHandlers": [
				{
					"options": {
						"tokens": [
							{
								"key": "row.Issue.value",
								"token": "selected_issue"
							},
							{
								"key": "row.Priority.value",
								"token": "selected_issue_priority"
							}
						]
					},
					"type": "drilldown.setToken"
				}
			],
			"options": {
				"backgroundColor": "#131a23",
				"columnFormat": {
					"Devices": {
						"textOverflow": "break-word"
					},
					"Issue": {
						"textOverflow": "break-word"
					},
					"Severity": {
						"rowBackgroundColors": "> table | seriesByName(\"Severity\") | matchValue(severityColors)",
						"textOverflow": "break-word"
					},
					"Sites": {
						"textOverflow": "break-word"
					}
				},
				"count": 15,
				"drilldown": "row",
				"fontSize": "small",
				"showInternalFields": false,
				"tableFormat": {
					"headerBackgroundColor": "#1c2738",
					"headerColor": "#ecf0f5"
				}
			},
			"title": "Issues",
			"type": "splunk.table"
		},
		"viz_ex_router_health": {
			"context": {
				"healthColorRange": [
					{
						"to": 80,
						"value": "#fa5762"
					},
					{
						"from": 80,
						"to": 95,
						"value": "#f0c243"
					},
					{
						"from": 95,
						"value": "#4cbf7f"
					}
				]
			},
			"dataSources": {
				"primary": "ds_mod_device_health_routers"
			},
			"description": "Reachable and managed routers as a percentage of total router inventory.",
			"options": {
				"backgroundColor": "#131a23",
				"gaugeColor": "> primary | seriesByName('health_pct') | lastPoint() | rangeValue(healthColorRange)",
				"labelDisplay": "percentage",
				"orientation": "horizontal",
				"value": "> primary | seriesByName('health_pct') | lastPoint()",
				"valueDisplay": "percentage"
			},
			"title": "Routers",
			"type": "splunk.fillergauge"
		},
		"viz_ex_switch_health": {
			"context": {
				"healthColorRange": [
					{
						"to": 80,
						"value": "#fa5762"
					},
					{
						"from": 80,
						"to": 95,
						"value": "#f0c243"
					},
					{
						"from": 95,
						"value": "#4cbf7f"
					}
				]
			},
			"dataSources": {
				"primary": "ds_mod_device_health_switches"
			},
