	"dataSources": {
		"ds_cs_by_ssid": {
			"name": "Client Summary - Clients by SSID",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\" type=\"Wireless\" \n| stats dc(macAddress) as clients by connection.ssid \n| rename connection.ssid as ssid ",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_count_over_time": {
			"name": "Client Summary - Client Count Over Time",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" (clientType=\"WIRED\" OR clientType=\"WIRELESS\") (scoreType=\"GOOD\" OR scoreType=\"FAIR\" OR scoreType=\"POOR\" OR scoreType=\"IDLE\" OR scoreType=\"NODATA\")\n| bin _time span=15m\n| stats latest(clientCount) as cc by _time, clientType, scoreType\n| stats sum(cc) as cc by _time, scoreType\n| eval \"Good Count\"=if(scoreType==\"GOOD\",cc,null()), \"Fair Count\"=if(scoreType==\"FAIR\",cc,null()), \"Poor Count\"=if(scoreType==\"POOR\",cc,null()), \"Idle Count\"=if(scoreType==\"IDLE\" OR scoreType==\"NODATA\",cc,null())\n| stats sum(\"Good Count\") as \"Good Count\", sum(\"Fair Count\") as \"Fair Count\", sum(\"Poor Count\") as \"Poor Count\", sum(\"Idle Count\") as \"Idle Count\" by _time",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_health_trend": {
			"name": "Client Health Score Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"ALL\" scoreType=\"ALL\" | timechart fixedrange=false latest(scoreValue) as \"Client Health Score\"",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cs_total_trend": {
			"name": "Total Connected Clients Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"ALL\" scoreType=\"ALL\" | timechart fixedrange=false latest(clientCount) as \"Total Connected Clients\"",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_kpi_cs_health": {
			"name": "KPI Client Health Score",
			"options": {
				"extend": "ds_cs_health_trend",
				"query": "| fields _time \"Client Health Score\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_cs_total": {
			"name": "KPI Total Connected Clients",
			"options": {
				"extend": "ds_cs_total_trend",
				"query": "| fields _time \"Total Connected Clients\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_wired_health": {
			"name": "KPI Wired Health",
			"options": {
				"extend": "ds_wired_health_trend",
				"query": "| fields _time \"Wired Health\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_wired_total": {
			"name": "KPI Wired Clients",
			"options": {
				"extend": "ds_wired_total_trend",
				"query": "| fields _time \"Wired Clients\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_wireless_health": {
			"name": "KPI Wireless Health",
			"options": {
				"extend": "ds_wireless_health_trend",
				"query": "| fields _time \"Wireless Health\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_wireless_total": {
			"name": "KPI Wireless Clients",
			"options": {
				"extend": "ds_wireless_total_trend",
				"query": "| fields _time \"Wireless Clients\""
			},
			"type": "ds.chain"
		},
		"ds_mod_base_device_health": {
			"name": "Modern base - Latest device health by DeviceID",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:devicehealth\"\n| stats latest(DeviceFamily) as DeviceFamily, latest(Reachability) as Reachability, latest(Manageability) as Manageability by DeviceID\n| eval DeviceType=case(match(DeviceFamily,\"(?i)ap|access.point|unified.ap\"),\"Access Points\", match(DeviceFamily,\"(?i)switch\"),\"Switches\", match(DeviceFamily,\"(?i)router\"),\"Routers\", match(DeviceFamily,\"(?i)firewall|asa|ftd|firepower\"),\"Firewalls\", 1==1,\"Other\")\n| eval healthy=if(Reachability=\"Reachable\" AND match(Manageability,\"^Managed\"),1,0)\n| eval HealthStatus=case(healthy=1,\"Healthy\", Reachability=\"Reachable\",\"Fair\", 1==1,\"Poor\")",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_mod_client_activity_7d": {
			"name": "Modern - Client activity and onboarding over 7 days",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\"\n| eval leafSiteId=mvindex(split(rtrim(siteHierarchyId,\"/\"),\"/\"),-1)\n| lookup site_topology_lookup id as leafSiteId OUTPUT Site as lookupSite, name as lookupSiteName\n| eval site_path=coalesce(siteHierarchy, lookupSite, lookupSiteName), rawSite=mvindex(split(site_path,\"/\"),-1)\n| eval Site=case(isnotnull(lookupSite) AND trim(lookupSite)!=\"\" AND lower(lookupSite)!=\"null\", lookupSite, isnotnull(rawSite) AND trim(rawSite)!=\"\" AND lower(rawSite)!=\"null\", rawSite, isnotnull(lookupSiteName) AND trim(lookupSiteName)!=\"\" AND lower(lookupSiteName)!=\"null\", lookupSiteName, true(), \"Unknown\")\n| search Site=\"$site_tok$\" type=\"$client_type_tok$\"\n| bin _time span=1d\n| stats dc(macAddress) as \"Active Clients\", avg(onboarding.avgAuthDuration) as avg_aaa, avg(onboarding.avgDhcpDuration) as avg_dhcp, avg(onboarding.avgAssocDuration) as avg_assoc by _time\n| eval \"Avg Onboarding (ms)\"=round(coalesce(avg_aaa,0)+coalesce(avg_dhcp,0)+coalesce(avg_assoc,0), 2)\n| fields _time \"Active Clients\" \"Avg Onboarding (ms)\"",
				"queryParameters": {
					"earliest": "-7d@d",
					"latest": "now"
				}
			},
			"type": "ds.search"
		},
		"ds_mod_client_details": {
			"name": "Modern - Client details table with filters",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\"\n| eval leafSiteId=mvindex(split(rtrim(siteHierarchyId,\"/\"),\"/\"),-1)\n| lookup site_topology_lookup id as leafSiteId OUTPUT Site as lookupSite, name as lookupSiteName\n| eval site_path=coalesce(siteHierarchy, lookupSite, lookupSiteName), rawSite=mvindex(split(site_path,\"/\"),-1)\n| eval Site=case(isnotnull(lookupSite) AND trim(lookupSite)!=\"\" AND lower(lookupSite)!=\"null\", lookupSite, isnotnull(rawSite) AND trim(rawSite)!=\"\" AND lower(rawSite)!=\"null\", rawSite, isnotnull(lookupSiteName) AND trim(lookupSiteName)!=\"\" AND lower(lookupSiteName)!=\"null\", lookupSiteName, true(), \"Unknown\")\n| search Site=\"$site_tok$\" type=\"$client_type_tok$\"\n| stats sum(traffic.usage) as usage, latest(deviceType) as device_type, latest(connection.ssid) as ssid, latest(connection.l3Vn) as vn, latest(connection.apMac) as ap, latest(type) as conn_type, latest(Site) as Site, latest(health.overallScore) as health by macAddress\n| eval usage_gb=tonumber(round(usage/1073741824,2)), ssid=case(isnotnull(ssid) AND ssid!=\"null\" AND ssid!=\"\", ssid, conn_type=\"Wired\" AND isnotnull(vn) AND vn!=\"null\", \"Wired (\".vn.\")\", conn_type=\"Wired\", \"Wired\", 1==1, \"Unknown\"), device_type=if(isnull(device_type) OR device_type=\"null\" OR device_type=\"\", \"Unknown\", device_type), health=round(health*10, 1)\n| where usage_gb > 0\n| sort -usage_gb\n| head 50\n| rename macAddress as Client, device_type as Type, ssid as SSID, ap as AP, usage_gb as \"Traffic (GB)\", health as \"Health %\"\n| table Client Type SSID AP Site \"Traffic (GB)\" \"Health %\"",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_mod_client_distribution_score": {
			"name": "Modern - Client good-health distribution score",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" (clientType=\"WIRED\" OR clientType=\"WIRELESS\") (scoreType=\"GOOD\" OR scoreType=\"FAIR\" OR scoreType=\"POOR\" OR scoreType=\"IDLE\" OR scoreType=\"NODATA\")\n| stats latest(clientCount) as clients by scoreType\n| stats sum(eval(if(scoreType=\"GOOD\",clients,0))) as healthy, sum(clients) as total\n| eval healthy_pct=if(total>0, round(healthy/total*100, 1), 0)\n| fields healthy_pct healthy total",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_mod_client_location_dist": {
			"name": "Modern - Client location distribution with filters",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\"\n| eval leafSiteId=mvindex(split(rtrim(siteHierarchyId,\"/\"),\"/\"),-1)\n| lookup site_topology_lookup id as leafSiteId OUTPUT Site as lookupSite, name as lookupSiteName\n| eval site_path=coalesce(siteHierarchy, lookupSite, lookupSiteName), rawSite=mvindex(split(site_path,\"/\"),-1)\n| eval Site=case(isnotnull(lookupSite) AND trim(lookupSite)!=\"\" AND lower(lookupSite)!=\"null\", lookupSite, isnotnull(rawSite) AND trim(rawSite)!=\"\" AND lower(rawSite)!=\"null\", rawSite, isnotnull(lookupSiteName) AND trim(lookupSiteName)!=\"\" AND lower(lookupSiteName)!=\"null\", lookupSiteName, true(), \"Unknown\")\n| search Site=\"$site_tok$\" type=\"$client_type_tok$\"\n| where Site!=\"Unknown\"\n| stats dc(macAddress) as Clients by Site\n| sort -Clients\n| head 20",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_mod_client_os_dist": {
			"name": "Modern - Client OS distribution with filters",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\"\n| eval leafSiteId=mvindex(split(rtrim(siteHierarchyId,\"/\"),\"/\"),-1)\n| lookup site_topology_lookup id as leafSiteId OUTPUT Site as lookupSite, name as lookupSiteName\n| eval site_path=coalesce(siteHierarchy, lookupSite, lookupSiteName), rawSite=mvindex(split(site_path,\"/\"),-1)\n| eval Site=case(isnotnull(lookupSite) AND trim(lookupSite)!=\"\" AND lower(lookupSite)!=\"null\", lookupSite, isnotnull(rawSite) AND trim(rawSite)!=\"\" AND lower(rawSite)!=\"null\", rawSite, isnotnull(lookupSiteName) AND trim(lookupSiteName)!=\"\" AND lower(lookupSiteName)!=\"null\", lookupSiteName, true(), \"Unknown\")\n| search Site=\"$site_tok$\" type=\"$client_type_tok$\"\n| eval osType=if(isnull(osType) OR osType=\"null\" OR osType=\"\" OR osType=\"Un-Classified Device\", \"Unknown\", osType)\n| stats dc(macAddress) as Clients by osType\n| sort -Clients\n| rename osType as \"OS\"",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_mod_device_health_ap": {
			"name": "Modern - Access Points health percent",
			"options": {
				"extend": "ds_mod_base_device_health",
				"query": "| search DeviceType=\"Access Points\"\n| stats count as total, sum(healthy) as healthy\n| eval health_pct=if(total>0, round(healthy/total*100, 1), 0)\n| fields health_pct healthy total"
			},
			"type": "ds.chain"
		},
		"ds_mod_device_health_distribution": {
			"name": "Modern - Fleet health distribution",
			"options": {
				"extend": "ds_mod_base_device_health",
				"query": "| stats count(eval(HealthStatus=\"Healthy\")) as Healthy, count(eval(HealthStatus=\"Fair\")) as Fair, count(eval(HealthStatus=\"Poor\")) as Poor\n| eval Fleet=\"All Devices\"\n| table Fleet Healthy Fair Poor"
			},
			"type": "ds.chain"
		},
		"ds_mod_device_health_firewalls": {
			"name": "Modern - Firewalls health percent",
			"options": {
				"extend": "ds_mod_base_device_health",
				"query": "| search DeviceType=\"Firewalls\"\n| stats count as total, sum(healthy) as healthy\n| eval health_pct=if(total>0, round(healthy/total*100, 1), 0)\n| fields health_pct healthy total"
			},
			"type": "ds.chain"
		},
		"ds_mod_device_health_routers": {
			"name": "Modern - Routers health percent",
			"options": {
				"extend": "ds_mod_base_device_health",
				"query": "| search DeviceType=\"Routers\"\n| stats count as total, sum(healthy) as healthy\n| eval health_pct=if(total>0, round(healthy/total*100, 1), 0)\n| fields health_pct healthy total"
			},
			"type": "ds.chain"
		},
		"ds_mod_device_health_switches": {
			"name": "Modern - Switches health percent",
			"options": {
				"extend": "ds_mod_base_device_health",
				"query": "| search DeviceType=\"Switches\"\n| stats count as total, sum(healthy) as healthy\n| eval health_pct=if(total>0, round(healthy/total*100, 1), 0)\n| fields health_pct healthy total"
			},
			"type": "ds.chain"
		},
		"ds_mod_device_inventory_bar": {
			"name": "Modern - Device inventory by type",
			"options": {
				"extend": "ds_mod_base_device_health",
				"query": "| stats count as Total, sum(healthy) as Healthy by DeviceType\n| eval NeedsAttention=Total-Healthy\n| sort -Total\n| rename DeviceType as \"Device Type\"\n| table \"Device Type\" Healthy NeedsAttention"
			},
			"type": "ds.chain"
		},
		"ds_mod_device_summary_total": {
			"name": "Modern - Total device summary",
			"options": {
				"extend": "ds_mod_base_device_health",
				"query": "| stats count as total, sum(healthy) as healthy\n| eval health_pct=if(total>0, round(healthy/total*100, 1), 0)\n| fields total healthy health_pct"
			},
			"type": "ds.chain"
		},
		"ds_mod_exec_issues_table": {
			"name": "Modern - Active issues table",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:issue\" IssueStatus=\"active\"\n| stats count as Count, latest(_time) as last_seen, values(DeviceName) as Devices, values(SiteName) as Sites by IssueName, IssueSpecificPriority, IssueSpecificCategory\n| eval Severity=case(IssueSpecificPriority=\"P1\",\"Critical\", IssueSpecificPriority=\"P2\",\"Warning\", IssueSpecificPriority=\"P3\",\"Notice\", IssueSpecificPriority=\"P4\",\"Info\", 1==1, coalesce(IssueSpecificPriority,\"Unknown\"))\n| eval Sites=mvjoin(Sites, \", \"), Devices=mvjoin(Devices, \", \"), \"Last Seen\"=strftime(last_seen, \"%Y-%m-%d %H:%M:%S\")\n| rename IssueName as Issue, IssueSpecificPriority as Priority, IssueSpecificCategory as Category\n| table Issue Priority Severity Category Count Sites Devices \"Last Seen\"",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_mod_past_week_client_trends": {
			"name": "Modern - 7 day wired and wireless client comparison",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" (clientType=\"WIRELESS\" OR clientType=\"WIRED\") scoreType=\"ALL\"\n| timechart span=1d latest(clientCount) as Clients by clientType\n| rename WIRELESS as \"Wireless Clients\", WIRED as \"Wired Clients\"",
				"queryParameters": {
					"earliest": "-7d@d",
					"latest": "now"
				}
			},
			"type": "ds.search"
		},
		"ds_mod_selected_issue_detail": {
			"name": "Modern - Selected issue detail",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:issue\" IssueStatus=\"active\" IssueName=\"$selected_issue$\"\n| stats latest(IssueSpecificPriority) as Priority, latest(IssueSpecificDescription) as Description, latest(IssueSpecificSummary) as Summary, latest(IssueSpecificCategory) as Category, latest(_time) as last_seen, values(DeviceName) as Devices, values(SiteName) as Sites by IssueID, IssueName\n| eval Why=coalesce(Description, Summary, \"No description available\"), Sites=mvjoin(Sites, \", \"), Devices=mvjoin(Devices, \", \"), \"Last Seen\"=strftime(last_seen, \"%Y-%m-%d %H:%M:%S\")\n| rename IssueName as Issue\n| table IssueID Issue Priority Category Why Sites Devices \"Last Seen\"",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_mod_wired_client_trend_health": {
			"name": "Modern - Wired client trend with health threshold overlays",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"WIRED\" (scoreType=\"ALL\" OR scoreType=\"GOOD\" OR scoreType=\"FAIR\" OR scoreType=\"POOR\" OR scoreType=\"IDLE\" OR scoreType=\"NODATA\")\n| timechart latest(eval(if(scoreType=\"GOOD\",clientCount,null()))) as Healthy, latest(eval(if(scoreType=\"FAIR\",clientCount,null()))) as Fair, latest(eval(if(scoreType=\"POOR\",clientCount,null()))) as Poor, latest(eval(if(scoreType=\"IDLE\" OR scoreType=\"NODATA\",clientCount,null()))) as \"No Data\", latest(eval(if(scoreType=\"ALL\",scoreValue,null()))) as \"Wired Health\"\n| eval \"Warning Threshold\"=80, \"Healthy Threshold\"=95",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_mod_wireless_client_trend_health": {
			"name": "Modern - Wireless client trend with health threshold overlays",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"WIRELESS\" (scoreType=\"ALL\" OR scoreType=\"GOOD\" OR scoreType=\"FAIR\" OR scoreType=\"POOR\" OR scoreType=\"IDLE\" OR scoreType=\"NODATA\")\n| timechart latest(eval(if(scoreType=\"GOOD\",clientCount,null()))) as Healthy, latest(eval(if(scoreType=\"FAIR\",clientCount,null()))) as Fair, latest(eval(if(scoreType=\"POOR\",clientCount,null()))) as Poor, latest(eval(if(scoreType=\"IDLE\" OR scoreType=\"NODATA\",clientCount,null()))) as \"No Data\", latest(eval(if(scoreType=\"ALL\",scoreValue,null()))) as \"Wireless Health\"\n| eval \"Warning Threshold\"=80, \"Healthy Threshold\"=95",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_wired_health_trend": {
			"name": "Wired Health Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"WIRED\" scoreType=\"ALL\" | timechart fixedrange=false latest(scoreValue) as \"Wired Health\"",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_wired_total_trend": {
			"name": "Wired Clients Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"WIRED\" scoreType=\"ALL\" | timechart fixedrange=false latest(clientCount) as \"Wired Clients\"",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_wired_trend_24h": {
			"name": "Statewide - Wired Client Trend 24h",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"WIRED\" (scoreType=\"GOOD\" OR scoreType=\"FAIR\" OR scoreType=\"POOR\" OR scoreType=\"IDLE\" OR scoreType=\"NODATA\")\n| timechart latest(eval(if(scoreType==\"GOOD\",clientCount,null()))) as Healthy, latest(eval(if(scoreType==\"FAIR\",clientCount,null()))) as Fair, latest(eval(if(scoreType==\"POOR\",clientCount,null()))) as Poor, latest(eval(if(scoreType==\"IDLE\" OR scoreType==\"NODATA\",clientCount,null()))) as \"No Data\"",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_wireless_health_trend": {
			"name": "Wireless Health Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"WIRELESS\" scoreType=\"ALL\" | timechart fixedrange=false latest(scoreValue) as \"Wireless Health\"",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_wireless_total_trend": {
			"name": "Wireless Clients Trend",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"WIRELESS\" scoreType=\"ALL\" | timechart fixedrange=false latest(clientCount) as \"Wireless Clients\"",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_wireless_trend_24h": {
			"name": "Statewide - Wireless Client Trend 24h",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:clienthealth\" clientType=\"WIRELESS\" (scoreType=\"GOOD\" OR scoreType=\"FAIR\" OR scoreType=\"POOR\" OR scoreType=\"IDLE\" OR scoreType=\"NODATA\")\n| timechart latest(eval(if(scoreType==\"GOOD\",clientCount,null()))) as Healthy, latest(eval(if(scoreType==\"FAIR\",clientCount,null()))) as Fair, latest(eval(if(scoreType==\"POOR\",clientCount,null()))) as Poor, latest(eval(if(scoreType==\"IDLE\" OR scoreType==\"NODATA\",clientCount,null()))) as \"No Data\"",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.search"
		}
